={
  "channel": "{{ $('Questo Outbound Leave Event').item.json.body.payload.approverEmail }}",
  "text": "🏖️ Leave Request: {{ $('Questo Outbound Leave Event').item.json.body.payload.employeeEmail }} ({{ $('Questo Outbound Leave Event').item.json.body.payload.daysCount }} days)",
  "blocks": [
    {
      "type": "header",
      "text": {
        "type": "plain_text",
        "text": "🏖️ New Leave / PTO Application"
      }
    },
    {
      "type": "section",
      "fields": [
        {
          "type": "mrkdwn",
          "text": "*Employee:* {{ $('Questo Outbound Leave Event').item.json.body.payload.employeeEmail }}"
        },
        {
          "type": "mrkdwn",
          "text": "*Role Tier:* {{ $('Questo Outbound Leave Event').item.json.body.payload.roleTier }}"
        },
        {
          "type": "mrkdwn",
          "text": "*Dates:* {{ $('Questo Outbound Leave Event').item.json.body.payload.startDate }} to {{ $('Questo Outbound Leave Event').item.json.body.payload.endDate }} ({{ $('Questo Outbound Leave Event').item.json.body.payload.daysCount }} days)"
        },
        {
          "type": "mrkdwn",
          "text": "*Type:* {{ $('Questo Outbound Leave Event').item.json.body.payload.leaveType }}"
        }
      ]
    },
    {
      "type": "section",
      "text": {
        "type": "mrkdwn",
        "text": "*Reason:*\n>{{ $('Questo Outbound Leave Event').item.json.body.payload.reason }}"
      }
    },
    {
      "type": "context",
      "elements": [
        {
          "type": "mrkdwn",
          "text": "ℹ️ Approving will *freeze their standup streak* and *auto-reschedule active tasks*."
        }
      ]
    }
  ]
}

={
  "action": "APPROVE_LEAVE",
  "token": "questo_secret_token_123",
  "data": {
    "leaveId": "{{ $('Questo Outbound Leave Event').item.json.body.payload.leaveId }}",
    "remarks": "Approved automatically via Manager Slack interaction."
  }
}
